#[path="/Users/chazu/dev/zig/birnam/rust/birnam-siphon/tests/support/minimal.rs"] mod minimal;
use birnam_abi::{Oop,as_size,size};
unsafe extern "C" { fn clock_gettime_nsec_np(clock:u32)->u64; }
fn main(){let h=minimal::native_floor();let q=h.scope();let gc=h.named(b"GC").unwrap();let at=q.keep(h.intern(b"atWord:").unwrap()).unwrap();let length=q.keep(h.intern(b"sizeWord").unwrap()).unwrap();
 for n in [16usize,8192,1<<20] {
  let input:Vec<_>=(0..n).map(|i|(i%256) as u8).collect();let provider=q.call(h.named(b"Bytes").unwrap(),b"fromBytes:",&[q.byte_values(&input).unwrap()]).unwrap();
  assert_eq!(q.read_bytes(provider).unwrap(),input);
  for sample in 0..6 {for mode in if sample%2==0 {["scalar","bulk"]}else{["bulk","scalar"]} {
   q.call(gc,b"collectPrecisely",&[]).unwrap();let calls=if n<8192 {1000}else if n<1<<20 {64}else{8};
   let start=unsafe{clock_gettime_nsec_np(16)};
   for _ in 0..calls {
    let bytes=if mode=="bulk" {q.read_bytes(provider).unwrap()}else{
     q.keep(provider).unwrap();let count=as_size(unsafe{h.id.send(provider,length,&[]).unwrap()}).unwrap();let mut out=Vec::with_capacity(count);
     for i in 0..count {let v=unsafe{h.id.send(provider,at,&[size(i).unwrap()]).unwrap()};out.push(u8::try_from(as_size(v).unwrap()).unwrap());}out
    };assert_eq!(bytes,input);
   }
   println!("{n} {mode} {calls} {}",unsafe{clock_gettime_nsec_np(16)}-start);
  }}
 }
}
